"""Generate the audit reports and reproducible views.

Every file produced here is a *generated artifact* (law #4): derived from the
event logs, never source truth. Each file carries a DO-NOT-EDIT banner and its
content hash is recorded in ``data/generated/GENERATED_MANIFEST.json`` so the
self-audit can detect hand edits (law #6: generated views must be reproducible).
"""

from __future__ import annotations

import json
import re
from typing import Any

from fek.kernel.canonical import canonical_json, sha256_hex
from fek.kernel.context import Kernel

BANNER = (
    "<!-- DO NOT EDIT. Generated by `fek generate-report`. "
    "Source of truth is data/events/*.jsonl. (law #4) -->"
)

MANIFEST_NAME = "GENERATED_MANIFEST.json"

STATUS_START = "<!-- FEK:GENERATED:START -->"
STATUS_END = "<!-- FEK:GENERATED:END -->"


# -- low-level helpers ---------------------------------------------------
def _write_generated(kernel: Kernel, relpath: str, content: str, manifest: dict[str, str]) -> None:
    path = kernel.root / relpath
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8")
    manifest[relpath] = sha256_hex(content)


def _md_table(headers: list[str], rows: list[list[Any]]) -> str:
    if not rows:
        return "_none_\n"
    out = ["| " + " | ".join(headers) + " |", "| " + " | ".join("---" for _ in headers) + " |"]
    for row in rows:
        out.append("| " + " | ".join(str(c) for c in row) + " |")
    return "\n".join(out) + "\n"


# -- report bodies -------------------------------------------------------
def _header(kernel: Kernel, title: str, state_root: str) -> str:
    return (
        f"# {title}\n\n{BANNER}\n\n"
        f"- generated_at: `{kernel.now()}`\n"
        f"- state_root: `{state_root}`\n"
        f"- note: a state_root proves integrity, not correctness (law #15)\n\n"
    )


def generate_all(kernel: Kernel) -> dict[str, Any]:
    """Generate every report + view, sync CURRENT_STATUS, write the manifest."""

    from fek.state.snapshot import snapshot, write_snapshot
    from fek.prose_claims import overclaim_report
    from fek.namespaces import graph_report, export_json as export_graph_json
    from fek.layers import load_layers, maturity_summary
    from fek.reviews import load_reviews
    from fek.reports.self_audit import run_self_audit

    snap = snapshot(kernel)
    state_root = snap["state_root"]
    over = overclaim_report(kernel)
    graph = graph_report(kernel)
    layers = load_layers(kernel)
    manifest: dict[str, str] = {}

    # evidence_report.md -- grades are RECOMPUTED, never read from a stale grade
    # event, so a refuted claim honestly reports EX_REFUTED (laws #2, #3, #11).
    from fek.evidence.grader import grade_claim

    rows = []
    honored_by_class: dict[str, int] = {}
    declared_by_class: dict[str, int] = {}
    for cid, claim in sorted(snap["claims"].items()):
        g = grade_claim(kernel, claim, emit=False)
        rows.append([cid, claim.get("status"), g.actual_grade, claim.get("claim_type")])
        honored_by_class[g.actual_grade] = honored_by_class.get(g.actual_grade, 0) + 1
        for rec in claim.get("current_evidence", []):
            ec = rec.get("evidence_class", "?")
            declared_by_class[ec] = declared_by_class.get(ec, 0) + 1
    body = _header(kernel, "Evidence Report", state_root)
    body += "## Claims by status\n\n" + _md_table(["status", "count"], sorted(snap["status_counts"].items()))
    body += "\n## Evidence counts by class (declared records)\n\n" + _md_table(
        ["evidence_class", "count"], sorted(declared_by_class.items())
    )
    body += "\n## Honored grade by class (recomputed)\n\n" + _md_table(
        ["honored_grade", "count"], sorted(honored_by_class.items())
    )
    body += "\n## Claims\n\n" + _md_table(["claim_id", "status", "honored_grade", "type"], rows)
    _write_generated(kernel, "reports/generated/evidence_report.md", body, manifest)

    # overclaim_report.md
    body = _header(kernel, "Overclaim Report", state_root)
    body += f"- total strong-claim spans: **{over['total_spans']}**\n"
    body += f"- overclaims (unsupported, not speculative): **{over['overclaim_count']}**\n\n"
    body += _md_table(
        ["file", "line", "word", "speculative", "source_map", "overclaim"],
        [[s["file"], s["line"], s["word"], s["speculative"], s["has_source_map"], s["is_overclaim"]] for s in over["spans"]],
    )
    _write_generated(kernel, "reports/generated/overclaim_report.md", body, manifest)

    # state_report.md
    from fek.state.store import EventStore

    denied = [e for e in EventStore(kernel).read("state") if e.type == "transition.denied"]
    denied_rows = []
    for e in denied:
        pol = e.payload.get("policy", {})
        first = next((r["reason"] for r in pol.get("results", []) if not r["allowed"]), "")
        denied_rows.append([e.payload.get("transition_id"), e.payload.get("claim_id"), first])
    body = _header(kernel, "State Report", state_root)
    body += "## Event counts\n\n" + _md_table(["log", "events"], sorted(snap["event_counts"].items()))
    body += "\n## Claim status counts\n\n" + _md_table(["status", "count"], sorted(snap["status_counts"].items()))
    body += f"\n## Refutations: {len(snap['refutations'])}  |  Quarantine: {len(snap['quarantine'])}\n"
    body += f"\n## Policy violations (denied transitions): {len(denied)}\n\n" + _md_table(
        ["transition_id", "claim_id", "first_reason"], denied_rows
    )
    body += f"\n## Granted capabilities\n\n{snap['granted_capabilities'] or '_none (deny-by-default)_'}\n"
    _write_generated(kernel, "reports/generated/state_report.md", body, manifest)

    # graph_report.md
    body = _header(kernel, "Graph Report", state_root)
    body += f"- instances: **{graph['instance_count']}**, acyclic: **{graph['acyclic']}**\n"
    body += f"- reference errors: {graph['ref_errors'] or 'none'}\n\n"
    body += "## Layer hierarchy (typed, not folders)\n\n"
    body += _md_table(
        ["index", "id", "name", "maturity", "status"],
        [[l.layer_index, l.id, l.name, l.maturity, l.status] for l in layers],
    )
    _write_generated(kernel, "reports/generated/graph_report.md", body, manifest)

    # reviewer_report.md
    reviews = load_reviews(kernel)
    body = _header(kernel, "Reviewer Report", state_root)
    body += _md_table(
        ["review_id", "subject", "reviewer", "decision"],
        [[r.review_id, r.subject_ref, r.reviewer, r.decision] for r in reviews],
    )
    _write_generated(kernel, "reports/generated/reviewer_report.md", body, manifest)

    # trust_report.md (self-audit summary)
    audit = run_self_audit(kernel)
    body = _header(kernel, "Trust Report", state_root)
    body += f"- self-audit: **{'PASS' if audit['passed'] else 'FAIL'}**\n"
    body += f"- policy violations (denied transitions): **{len(denied)}**\n\n"
    body += _md_table(
        ["check", "passed", "detail"],
        [[c["id"], c["passed"], c["detail"]] for c in audit["checks"]],
    )
    body += "\n## Maturity summary (layers)\n\n" + _md_table(["maturity", "count"], sorted(maturity_summary(kernel).items()))
    _write_generated(kernel, "reports/generated/trust_report.md", body, manifest)

    # artifact_report.md
    body = _header(kernel, "Artifact Report", state_root)
    body += "Reproducibility artifact summary. See `artifact/REPRODUCE.md`.\n\n"
    body += f"- claims: {sum(snap['status_counts'].values())}\n- state_root: `{state_root}`\n"
    body += f"- overclaims: {over['overclaim_count']}\n- policy_violations: {len(denied)}\n"
    body += f"- self_audit: {'PASS' if audit['passed'] else 'FAIL'}\n"
    _write_generated(kernel, "reports/generated/artifact_report.md", body, manifest)

    # generated JSON views
    export_graph_json(kernel)
    write_snapshot(kernel)

    # sync CURRENT_STATUS generated block (tracked in manifest)
    _sync_current_status(kernel, snap, audit, manifest)

    # write manifest LAST so it reflects all generated files
    _write_manifest(kernel, manifest)
    return {"state_root": state_root, "generated": sorted(manifest), "self_audit_passed": audit["passed"]}


def _status_block(kernel: Kernel, snap: dict[str, Any], audit: dict[str, Any]) -> str:
    from fek.layers import load_layers

    live = [l.name for l in load_layers(kernel) if l.maturity == "live"]
    experimental = [l.name for l in load_layers(kernel) if l.maturity == "experimental"]
    spec_only = [l.name for l in load_layers(kernel) if l.maturity == "spec_only"]
    lines = [
        STATUS_START,
        BANNER,
        f"- state_root: `{snap['state_root']}`",
        f"- claims: {sum(snap['status_counts'].values())}  status_counts: {snap['status_counts']}",
        f"- self_audit: {'PASS' if audit['passed'] else 'FAIL'}",
        f"- live layers: {live}",
        f"- experimental layers: {experimental}",
        f"- spec_only layers: {spec_only}",
        STATUS_END,
    ]
    return "\n".join(lines)


def _sync_current_status(kernel: Kernel, snap: dict[str, Any], audit: dict[str, Any], manifest: dict[str, str]) -> None:
    path = kernel.root / "CURRENT_STATUS.md"
    block = _status_block(kernel, snap, audit)
    text = path.read_text(encoding="utf-8") if path.exists() else "# Current Status\n\n"
    pattern = re.compile(re.escape(STATUS_START) + r".*?" + re.escape(STATUS_END), re.DOTALL)
    if pattern.search(text):
        text = pattern.sub(block, text)
    else:
        text = text.rstrip() + "\n\n" + block + "\n"
    path.write_text(text, encoding="utf-8")
    # track only the generated block hash (the rest is human prose)
    manifest["CURRENT_STATUS.md#generated_block"] = sha256_hex(block)


def _write_manifest(kernel: Kernel, manifest: dict[str, str]) -> None:
    kernel.paths.generated.mkdir(parents=True, exist_ok=True)
    (kernel.paths.generated / MANIFEST_NAME).write_text(canonical_json(manifest), encoding="utf-8")


def load_manifest(kernel: Kernel) -> dict[str, str]:
    path = kernel.paths.generated / MANIFEST_NAME
    if not path.exists():
        return {}
    return json.loads(path.read_text(encoding="utf-8"))


def current_block_hash(kernel: Kernel) -> str | None:
    path = kernel.root / "CURRENT_STATUS.md"
    if not path.exists():
        return None
    m = re.search(re.escape(STATUS_START) + r".*?" + re.escape(STATUS_END), path.read_text(encoding="utf-8"), re.DOTALL)
    return sha256_hex(m.group(0)) if m else None


__all__ = ["generate_all", "load_manifest", "current_block_hash", "BANNER", "MANIFEST_NAME"]
